using System.Reflection;
using System.Text.Json;
using LastEpochLAN.Mod.OfflineTools;
var labels=new List<string>();
void Check(bool good,string label){if(!good)throw new Exception(label);labels.Add(label);}
var writeEntry=typeof(DeathHitchTrace).GetMethod("Record",BindingFlags.Static|BindingFlags.NonPublic);
for(int i=0;i<80;i++)writeEntry.Invoke(null,new object[]{i,"Dying.onEnter",250d,(long)i,1,0,0});
var snapshot=DeathHitchTrace.Read();
var json=JsonSerializer.SerializeToElement(snapshot);var entries=json.GetProperty("entries");
Check(entries.GetArrayLength()==64,"history stays bounded after more than 64 stalls");
Check(entries[0].GetProperty("Frame").GetInt32()==16 && entries[63].GetProperty("Frame").GetInt32()==79,"report preserves chronological order and newest events");
Check(entries[0].GetProperty("Milliseconds").GetDouble()==250 && entries[0].GetProperty("Gc0").GetInt32()==1 && entries[0].GetProperty("UtcTicks").GetInt64()>0,"private trace entries serialize timing, GC and timestamp into runtime report");
writeEntry.Invoke(null,new object[]{80,"other",300d,0L,0,0,0});
Check(JsonSerializer.SerializeToElement(snapshot).GetProperty("entries")[63].GetProperty("Frame").GetInt32()==79,"async report snapshot is independent of later ring writes");
var finalizer=typeof(OfflineDeathHitchTracePatch).GetMethod("Finalizer",BindingFlags.NonPublic|BindingFlags.Static);
var targets=typeof(OfflineDeathHitchTracePatch).GetMethod("TargetMethods",BindingFlags.NonPublic|BindingFlags.Static);
var methods=((IEnumerable<MethodBase>)targets.Invoke(null,null)).ToArray();
Check(methods.All(m=>m!=null) && methods.Single(m=>m.Name=="pickupItem").GetParameters().Length==3,"diagnostic selects the native three-argument pickup overload without ambiguity");
var error=new InvalidOperationException("native failure");
Check(ReferenceEquals(finalizer.Invoke(null,new object[]{default(DeathHitchTrace.Sample),error}),error),"diagnostic finalizer preserves original native exception");
Directory.CreateDirectory("validation");File.WriteAllText("validation/death-hitch-fixture.json",JsonSerializer.Serialize(new{passed=labels.Count,checks=labels},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("PASS "+labels.Count+" death-hitch diagnostic checks");
